('العبادات', 1, 'كم عدد الصلوات المفروضة على المسلم في اليوم والليلة؟', '["ثلاث", "أربع", "خمس", "ست"]'::jsonb, 2, 'فرض الله خمس صلوات في اليوم والليلة: الفجر والظهر والعصر والمغرب والعشاء.', 'صحيح البخاري، كتاب الصلاة، باب كيف فرضت الصلاة في الإسراء', 'https://dorar.net/hadith', false),
('القرآن الكريم وعلومه', 1, 'ما أول سورة في ترتيب المصحف؟', '["البقرة", "الفاتحة", "الإخلاص", "الناس"]'::jsonb, 1, 'سورة الفاتحة هي أول سور المصحف، وتسمى أم الكتاب، وعدد آياتها سبع.', 'القرآن الكريم، سورة الفاتحة', 'https://quran.com/1', false),
('العبادات', 1, 'كم عدد أركان الإسلام؟', '["ثلاثة", "أربعة", "خمسة", "ستة"]'::jsonb, 2, 'أركان الإسلام خمسة: الشهادتان، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت لمن استطاع إليه سبيلا.', 'حديث «بني الإسلام على خمس» — رواه البخاري ومسلم', 'https://dorar.net/hadith', false),
('العبادات', 1, 'في أي شهر هجري فُرض صيام المسلمين؟', '["شعبان", "رمضان", "ذو الحجة", "محرم"]'::jsonb, 1, 'قال تعالى: «شَهْرُ رَمَضَانَ الَّذِي أُنزِلَ فِيهِ الْقُرْآنُ»، وفيه فُرض الصيام.', 'القرآن الكريم، سورة البقرة، الآية 185', 'https://quran.com/2/185', false),
('الأنبياء والرسل', 1, 'من النبيان اللذان رفعا قواعد الكعبة؟', '["نوح وهود", "إبراهيم وإسماعيل", "موسى وهارون", "يعقوب ويوسف"]'::jsonb, 1, 'قال تعالى: «وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ وَإِسْمَاعِيلُ».', 'القرآن الكريم، سورة البقرة، الآية 127', 'https://quran.com/2/127', false),
('السيرة النبوية', 1, 'في أي مدينة وُلد النبي محمد ﷺ؟', '["المدينة المنورة", "الطائف", "مكة المكرمة", "القدس"]'::jsonb, 2, 'وُلد النبي ﷺ في مكة المكرمة في عام الفيل.', 'السيرة النبوية لابن هشام', null, false),
('الأنبياء والرسل', 1, 'ما اسم الملَك الذي نزل بالوحي على النبي ﷺ؟', '["ميكائيل", "إسرافيل", "جبريل", "مالك"]'::jsonb, 2, 'هو جبريل عليه السلام، وقد ذكره الله باسمه في القرآن: «قُلْ مَن كَانَ عَدُوًّا لِّجِبْرِيلَ فَإِنَّهُ نَزَّلَهُ عَلَىٰ قَلْبِكَ».', 'القرآن الكريم، سورة البقرة، الآية 97', 'https://quran.com/2/97', false),
('السيرة النبوية', 1, 'ما اسم الغار الذي نزل فيه الوحي أول مرة على النبي ﷺ؟', '["غار ثور", "غار حراء", "غار الكهف", "غار أحد"]'::jsonb, 1, 'كان النبي ﷺ يتعبد في غار حراء، وفيه جاءه جبريل عليه السلام بأول الوحي.', 'صحيح البخاري، كتاب بدء الوحي', 'https://dorar.net/hadith', false),
('العبادات', 1, 'إلى أي جهة يتجه المسلمون في صلاتهم؟', '["بيت المقدس", "المسجد النبوي", "الكعبة المشرفة", "جبل عرفة"]'::jsonb, 2, 'قال تعالى: «فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ».', 'القرآن الكريم، سورة البقرة، الآية 144', 'https://quran.com/2/144', false),
('السيرة النبوية', 1, 'ما اسم أم النبي محمد ﷺ؟', '["حليمة السعدية", "آمنة بنت وهب", "خديجة بنت خويلد", "فاطمة بنت أسد"]'::jsonb, 1, 'أمه ﷺ هي آمنة بنت وهب، وحليمة السعدية هي مرضعته.', 'السيرة النبوية لابن هشام', null, false),
('القرآن الكريم وعلومه', 1, 'ما أطول سورة في القرآن الكريم؟', '["آل عمران", "النساء", "البقرة", "الأعراف"]'::jsonb, 2, 'أطول السور سورة البقرة، وعدد آياتها 286.', 'القرآن الكريم، سورة البقرة', 'https://quran.com/2', false),
('الأذكار والأدعية', 1, 'ماذا يقول المسلم قبل أن يبدأ الطعام؟', '["الحمد لله", "بسم الله", "الله أكبر", "سبحان الله"]'::jsonb, 1, 'السنة التسمية عند بدء الطعام، وإن نسيها قال: «بسم الله أوله وآخره».', 'صحيح البخاري، كتاب الأطعمة، باب التسمية على الطعام', 'https://dorar.net/hadith', false),
('القرآن الكريم وعلومه', 2, 'كم عدد سور القرآن الكريم؟', '["110", "114", "120", "124"]'::jsonb, 1, 'عدد سور القرآن الكريم 114 سورة، أولها الفاتحة وآخرها الناس.', 'مجمع الملك فهد لطباعة المصحف الشريف', 'https://qurancomplex.gov.sa/', false),
('القرآن الكريم وعلومه', 2, 'ما السورة التي لا تبدأ بالبسملة؟', '["الأنفال", "التوبة", "يونس", "هود"]'::jsonb, 1, 'سورة التوبة هي السورة الوحيدة التي لم تُفتتح بالبسملة.', 'القرآن الكريم، سورة التوبة', 'https://quran.com/9', false),
('التاريخ الإسلامي', 2, 'من أول مؤذن في الإسلام؟', '["بلال بن رباح", "عبد الله بن أم مكتوم", "أبو محذورة", "سعد القرظ"]'::jsonb, 0, 'أمر النبي ﷺ بلالًا بالأذان بعد رؤيا عبد الله بن زيد رضي الله عنهما.', 'صحيح البخاري، كتاب الأذان، باب بدء الأذان', 'https://dorar.net/hadith', false),
('السيرة النبوية', 2, 'ما اسم أول غزوة كبرى بين المسلمين وقريش، وقعت في رمضان من السنة الثانية للهجرة؟', '["أحد", "بدر", "الخندق", "حنين"]'::jsonb, 1, 'غزوة بدر الكبرى، وقد قال تعالى: «وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ».', 'القرآن الكريم، سورة آل عمران، الآية 123', 'https://quran.com/3/123', false),
('العبادات', 2, 'ما حكم صلاة الجمعة في حق الرجل المسلم المقيم القادر؟', '["سنة مؤكدة", "مستحبة", "فرض", "مباحة"]'::jsonb, 2, 'قال تعالى: «إِذَا نُودِيَ لِلصَّلَاةِ مِن يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَىٰ ذِكْرِ اللَّهِ»، والأمر يفيد الوجوب.', 'القرآن الكريم، سورة الجمعة، الآية 9', 'https://quran.com/62/9', false),
('السيرة النبوية', 2, 'من هي أول زوجات النبي ﷺ؟', '["عائشة", "حفصة", "خديجة بنت خويلد", "سودة بنت زمعة"]'::jsonb, 2, 'خديجة بنت خويلد رضي الله عنها، ولم يتزوج النبي ﷺ عليها حتى توفيت.', 'السيرة النبوية لابن هشام', null, false),
('العبادات', 2, 'في أي مكان يقف الحجاج يوم التاسع من ذي الحجة؟', '["مزدلفة", "منى", "عرفة", "الحجر"]'::jsonb, 2, 'الوقوف بعرفة ركن الحج الأعظم، وقد قال ﷺ: «الحج عرفة».', 'سنن أبي داود وسنن الترمذي، كتاب الحج', 'https://dorar.net/hadith', false),
('الأنبياء والرسل', 2, 'من النبي الذي التقمه الحوت؟', '["يونس", "أيوب", "إلياس", "زكريا"]'::jsonb, 0, 'هو يونس عليه السلام، قال تعالى: «وَإِنَّ يُونُسَ لَمِنَ الْمُرْسَلِينَ ... فَالْتَقَمَهُ الْحُوتُ».', 'القرآن الكريم، سورة الصافات، الآيات 139–142', 'https://quran.com/37/139', false),
('الأنبياء والرسل', 2, 'من النبي الذي خصه الله بالتكليم؟', '["عيسى", "موسى", "داود", "سليمان"]'::jsonb, 1, 'قال تعالى: «وَكَلَّمَ اللَّهُ مُوسَىٰ تَكْلِيمًا».', 'القرآن الكريم، سورة النساء، الآية 164', 'https://quran.com/4/164', false),
('الأحاديث النبوية', 2, 'ما أعظم آية في كتاب الله كما ورد في حديث أبيّ بن كعب رضي الله عنه؟', '["آية الكرسي", "آية الدين", "خواتيم سورة الحشر", "أول آل عمران"]'::jsonb, 0, 'سأل النبي ﷺ أبيًّا عن أعظم آية فقال: آية الكرسي، فضرب في صدره وقال: «ليهنك العلم أبا المنذر».', 'صحيح مسلم، كتاب صلاة المسافرين', 'https://dorar.net/hadith', false),
('الأحاديث النبوية', 2, 'أي سورة أخبر النبي ﷺ أنها تعدل ثلث القرآن؟', '["الفاتحة", "الإخلاص", "الكافرون", "الفلق"]'::jsonb, 1, 'أخبر ﷺ أن «قل هو الله أحد» تعدل ثلث القرآن.', 'صحيح البخاري، كتاب فضائل القرآن', 'https://dorar.net/hadith', false),
('الأذكار والأدعية', 2, 'كم مرة يُقال «سبحان الله» بعد الصلاة المفروضة في الحديث الصحيح؟', '["10", "25", "33", "100"]'::jsonb, 2, 'يسبّح المصلي ثلاثًا وثلاثين، ويحمد ثلاثًا وثلاثين، ويكبّر ثلاثًا وثلاثين، ثم يختم بالتهليل.', 'صحيح مسلم، كتاب المساجد، باب استحباب الذكر بعد الصلاة', 'https://dorar.net/hadith', false),
('القرآن الكريم وعلومه', 3, 'في أي سورة ورد اسم «أحمد» في القرآن الكريم؟', '["الصف", "الفتح", "محمد", "آل عمران"]'::jsonb, 0, 'قال تعالى على لسان عيسى عليه السلام: «وَمُبَشِّرًا بِرَسُولٍ يَأْتِي مِن بَعْدِي اسْمُهُ أَحْمَدُ».', 'القرآن الكريم، سورة الصف، الآية 6', 'https://quran.com/61/6', false),
('القرآن الكريم وعلومه', 3, 'كم مرة ورد اسم «محمد» ﷺ صريحًا في القرآن الكريم؟', '["مرتين", "ثلاث مرات", "أربع مرات", "خمس مرات"]'::jsonb, 2, 'ورد في آل عمران (144)، والأحزاب (40)، ومحمد (2)، والفتح (29).', 'القرآن الكريم', 'https://quran.com/', false),
('السيرة النبوية', 3, 'في أي سنة هجرية كان فتح مكة؟', '["السنة 6", "السنة 7", "السنة 8", "السنة 10"]'::jsonb, 2, 'فُتحت مكة في رمضان من السنة الثامنة للهجرة.', 'السيرة النبوية لابن هشام', null, false),
('السيرة النبوية', 3, 'في شأن أي غزوة نزلت سورة الحشر؟', '["بني قريظة", "بني النضير", "بني قينقاع", "خيبر"]'::jsonb, 1, 'نزلت في إجلاء بني النضير، وقد سماها ابن عباس رضي الله عنهما «سورة النضير».', 'صحيح البخاري، كتاب التفسير، سورة الحشر', 'https://dorar.net/hadith', false),
('القرآن الكريم وعلومه', 3, 'ما اسم أطول آية في القرآن الكريم؟', '["آية الكرسي", "آية الدَّيْن", "آية النور", "آية الوضوء"]'::jsonb, 1, 'أطول آية هي آية الدَّيْن، وهي الآية 282 من سورة البقرة.', 'القرآن الكريم، سورة البقرة، الآية 282', 'https://quran.com/2/282', false),
('الأحاديث النبوية', 3, 'كم عدد أبواب الجنة كما ورد في الحديث الصحيح؟', '["سبعة", "ثمانية", "عشرة", "اثنا عشر"]'::jsonb, 1, 'قال ﷺ: «في الجنة ثمانية أبواب، فيها باب يسمى الريان لا يدخله إلا الصائمون».', 'صحيح البخاري، كتاب بدء الخلق', 'https://dorar.net/hadith', false),
('التاريخ الإسلامي', 3, 'أي الصحابة لُقّب بـ«سيف الله المسلول»؟', '["خالد بن الوليد", "عمرو بن العاص", "سعد بن أبي وقاص", "أبو عبيدة بن الجراح"]'::jsonb, 0, 'لُقّب بذلك خالد بن الوليد رضي الله عنه، وقد وصفه النبي ﷺ بأنه «سيف من سيوف الله».', 'صحيح البخاري، كتاب المغازي', 'https://dorar.net/hadith', false),
('السيرة النبوية', 3, 'في أي موضع عُقدت بيعة الرضوان؟', '["بدر", "الحديبية", "أحد", "حنين"]'::jsonb, 1, 'بايع الصحابة النبي ﷺ تحت الشجرة بالحديبية، قال تعالى: «لَّقَدْ رَضِيَ اللَّهُ عَنِ الْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ الشَّجَرَةِ».', 'القرآن الكريم، سورة الفتح، الآية 18', 'https://quran.com/48/18', false),
('الأنبياء والرسل', 3, 'كم عدد الأنبياء المذكورين بأسمائهم في القرآن الكريم؟', '["20", "25", "30", "40"]'::jsonb, 1, 'ذُكر في القرآن الكريم خمسة وعشرون نبيًّا ورسولًا بأسمائهم.', 'تفسير ابن كثير، أحوال الأنبياء المذكورين في القرآن', null, false),
('الأنبياء والرسل', 3, 'ما اسم والد إبراهيم عليه السلام كما ورد في القرآن الكريم؟', '["عمران", "آزر", "لاوي", "ناحور"]'::jsonb, 1, 'قال تعالى: «وَإِذْ قَالَ إِبْرَاهِيمُ لِأَبِيهِ آزَرَ أَتَتَّخِذُ أَصْنَامًا آلِهَةً».', 'القرآن الكريم، سورة الأنعام، الآية 74', 'https://quran.com/6/74', false),
('التاريخ الإسلامي', 3, 'من هي أول شهيدة في الإسلام؟', '["سمية بنت خياط", "خديجة بنت خويلد", "أم عمارة", "الخنساء"]'::jsonb, 0, 'سمية بنت خياط أم عمار رضي الله عنهما، استُشهدت تحت التعذيب في مكة.', 'السيرة النبوية لابن هشام', null, false),
('القرآن الكريم وعلومه', 3, 'كم عدد الأحزاب في المصحف الشريف؟', '["30", "40", "60", "114"]'::jsonb, 2, 'المصحف مقسم إلى 30 جزءًا، وكل جزء حزبان، فالمجموع 60 حزبًا.', 'مجمع الملك فهد لطباعة المصحف الشريف', 'https://qurancomplex.gov.sa/', false)
